// INF-17: Alert on PRs open >24h without review on nabitllc repos
const GH_TOKEN = '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';
const TELEGRAM_USER = '5084875115';
const REPOS = ['nabitllc/kaos-mission-control', 'nabitllc/vespera'];
const STALE_HOURS = 24;

const staticData = this.getWorkflowStaticData('global');
if (!staticData.alertedPRs) staticData.alertedPRs = {};

const now = Date.now();
const staleMs = STALE_HOURS * 60 * 60 * 1000;

// Prune alerted PRs older than 7 days (re-alert after week if still open)
for (const [key, ts] of Object.entries(staticData.alertedPRs)) {
  if (now - ts > 7 * 24 * 60 * 60 * 1000) delete staticData.alertedPRs[key];
}

const ghHeaders = {
  'Authorization': 'Bearer ' + GH_TOKEN,
  'Accept': 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'KAOS-n8n-agent'
};

const {execSync} = require('child_process');
const stalePRs = [];

for (const repo of REPOS) {
  let prs;
  try {
    prs = await helpers.httpRequest({
      method: 'GET',
      url: 'https://api.github.com/repos/' + repo + '/pulls?state=open&per_page=20&sort=created&direction=asc',
      headers: ghHeaders
    });
  } catch(e) {
    continue;
  }

  for (const pr of prs) {
    const prKey = repo + '#' + pr.number;
    const createdAt = new Date(pr.created_at).getTime();
    const ageMs = now - createdAt;

    if (ageMs < staleMs) continue; // Not stale yet
    if (staticData.alertedPRs[prKey]) continue; // Already alerted

    // Check if it has any reviews
    let reviews = [];
    try {
      reviews = await helpers.httpRequest({
        method: 'GET',
        url: 'https://api.github.com/repos/' + repo + '/pulls/' + pr.number + '/reviews',
        headers: ghHeaders
      });
    } catch(e) {}

    if (reviews.length > 0) continue; // Has review activity, skip

    const ageHours = Math.round(ageMs / (60 * 60 * 1000));
    stalePRs.push({
      repo,
      prNumber: pr.number,
      title: pr.title,
      url: pr.html_url,
      ageHours,
      author: pr.user.login
    });
    staticData.alertedPRs[prKey] = now;
  }
}

if (stalePRs.length > 0) {
  const lines = stalePRs.map(p => {
    const repoShort = p.repo.split('/')[1];
    return `\u2022 [${repoShort}] ${p.title.slice(0, 70)}\n  Age: ${p.ageHours}h | Author: ${p.author}\n  ${p.url}`;
  }).join('\n\n');

  const msg = `\u23f0 Stale PRs — ${stalePRs.length} PR(s) open >24h without review\n\n${lines}`;

  try {
    execSync('openclaw message send --channel telegram --target ' + TELEGRAM_USER + ' --message ' + JSON.stringify(msg) + ' 2>/dev/null', {timeout: 15000, stdio: 'pipe'});
  } catch(e) {}
}

return [{ json: {
  stale_count: stalePRs.length,
  stale_prs: stalePRs,
  timestamp: new Date().toISOString()
} }];
